final class Scope {
    private final Scope parent;                 // null at the root scope
    private final Map<String, Symbol> symbols = new HashMap<>();
    Scope(Scope parent) { this.parent = parent; }
    boolean define(String n, Symbol s) { return symbols.putIfAbsent(n, s) == null; }  // dup -> false
    Symbol lookup(String name) {                // innermost outward
        for (Scope s = this; s != null; s = s.parent)
            if (s.symbols.containsKey(name)) return s.symbols.get(name);
        return null;
    }
}

